export const RANKS=[...Array.from({length:18},(_,i)=>({id:(18-i)+'k',label:(18-i)+'급'})),...Array.from({length:9},(_,i)=>({id:(i+1)+'d',label:i===0?'초단':(i+1)+'단'}))];
export function rankFor(raw={}){return RANKS.some(r=>r.id===raw.rank)?raw.rank:['18k','15k','12k','9k','6k','3k','1d'][Math.max(0,Math.min(6,Number(raw.level)||0))]}
export function rankLabel(raw){return RANKS.find(r=>r.id===rankFor(raw)).label}
export function pickHumanMove(state,analysis,isLegal,random=Math.random){const policy=analysis.humanPolicy;if(!policy||policy.length!==state.size*state.size+1)throw new Error('급수별 모델을 준비하지 못했습니다. 다시 시도해 주세요.');const best=analysis.moves?.[0];if(best&&best.x<0&&best.y<0&&isLegal(-1))return -1;let sum=0;const moves=[];for(let i=0;i<state.size*state.size;i++){if(policy[i]>0&&isLegal(i)){sum+=policy[i];moves.push([i,policy[i]])}}if(!(sum>0)){if(isLegal(-1))return -1;throw new Error('급수별 합법 수가 없습니다.')}let target=random()*sum;for(const [i,p]of moves){target-=p;if(target<=0)return i}return moves.at(-1)[0]}
